    def test_decorator(self, fo, patch_timer):
        """
        time works with functions returning Deferreds.
        """
        @tx.time(fo)
        def func():
            return succeed(42)

        rv = func()

        # Twisted runs fires callbacks immediately.
        assert [1] == fo._observed
        assert 42 == (yield rv)
        assert [1] == fo._observed

    @pytest.inlineCallbacks
