        """
        Does not swallow exceptions.
        """
        v = ValueError("foo")

        @tx.time(fo)
        def func():
            return fail(v)

        with pytest.raises(ValueError) as e:
            yield func()

        assert v is e.value

    @pytest.inlineCallbacks
    def test_deferred(self, fo, patch_timer):
        """
        time works with Deferreds.
        """
        d = tx.time(fo, Deferred())

        assert [] == fo._observed

        d.callback(42)

        assert 42 == (yield d)
        assert [1] == fo._observed

